-- Landscaping gets a section of its own.
--
-- It was answerable in the account setup wizard from the start and led
-- nowhere: the industry pointed at Field Reports, so a grounds contractor who
-- said what they do got the same general library as everyone else, and
-- `tradeCategoryFor` deliberately returned null so nothing was badged "Your
-- trade". Honest, and not much use.
--
-- Three templates, the shape a grounds business actually files:
--
--   * the recurring visit  - what was cut and cleared, before and after;
--   * the installation     - what was planted, the irrigation as-built, the
--                            establishment schedule and the warranty;
--   * the survey and quote - measured areas and a priced scope, done on site.
--
-- 'Landscaping' joins CATEGORY_ORDER in
-- apps/web/src/lib/template-categories.ts in the same change, and the
-- landscaping industry in packages/shared/src/industries.ts gains a
-- `tradeCategory` pointing at it. Starter checklists, workflows and reports
-- are added alongside, so the trade leads on every Templates tab rather than
-- on one of them.
--
-- Ownerless built-ins (team_id IS NULL AND created_by IS NULL), so the read
-- policy from 20260803000000 already covers them and nobody can edit one in
-- place. "Duplicate to edit" is the way in, same as the rest of the library.
--
-- Bodies use [bracketed] blanks rather than filler prose, per 20260824000000.
--
-- Requires 20260803000000 (nullable created_by, unique slug index). No schema
-- change of its own, so this takes row locks only.
--
-- Idempotent - ON CONFLICT (slug) DO UPDATE. Safe to re-run.
-- Apply manually in the Supabase SQL editor (or `supabase db push`).

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-landscaping-maintenance-visit',
  NULL,
  NULL,
  'Grounds Maintenance Visit',
  jsonb_build_object(
    'style', 'report',
    'category', 'Landscaping',
    'description', 'The recurring visit record: what was cut, edged, pruned and cleared, with before and after photos a property manager can approve from their desk.',
    'html', $html$<h1>Grounds Maintenance Visit</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><strong>Client:</strong> {{client_name}} &nbsp;·&nbsp; <strong>Conditions:</strong> {{weather}}</p><p><em><span style="color: rgb(140,148,162)">Photograph the same angles every visit. That is what makes the record worth keeping.</span></em></p><h2>Visit</h2><table><tbody><tr><th><p>Visit type</p></th><th><p>On site</p></th><th><p>Off site</p></th><th><p>Crew size</p></th><th><p>Next visit</p></th></tr><tr><td><p>[Scheduled or callout]</p></td><td><p>[Time]</p></td><td><p>[Time]</p></td><td><p>[How many]</p></td><td><p>[Date]</p></td></tr></tbody></table><h2>Work completed</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Lawns mown and edges cut</p></li><li data-type="taskItem" data-checked="false"><p>Clippings collected and removed</p></li><li data-type="taskItem" data-checked="false"><p>Beds weeded and mulch topped up</p></li><li data-type="taskItem" data-checked="false"><p>Shrubs and hedges trimmed</p></li><li data-type="taskItem" data-checked="false"><p>Paths, drives and car park blown clear</p></li><li data-type="taskItem" data-checked="false"><p>Litter and debris removed</p></li><li data-type="taskItem" data-checked="false"><p>Irrigation checked and running</p></li><li data-type="taskItem" data-checked="false"><p>Gates, fences and furniture checked</p></li></ul><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EBefore%20-%20main%20area%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Before - main area"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EAfter%20-%20main%20area%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="After - main area"></p><h2>Areas covered</h2><table><tbody><tr><th><p>Area</p></th><th><p>Work done</p></th><th><p>Condition</p></th><th><p>Notes</p></th></tr><tr><td><p>Front lawn and beds</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Rear lawn and beds</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Car park and paths</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Boundaries and hedges</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EBefore%20-%20secondary%20area%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Before - secondary area"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EAfter%20-%20secondary%20area%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="After - secondary area"></p><h2>Plant health and problems</h2><p><em><span style="color: rgb(140,148,162)">Anything that will get worse before the next visit belongs here.</span></em></p><table><tbody><tr><th><p>What you saw</p></th><th><p>Where</p></th><th><p>Likely cause</p></th><th><p>Recommended action</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Materials used</h2><table><tbody><tr><th><p>Material</p></th><th><p>Quantity</p></th><th><p>Where applied</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Safety and access</h2><p>[Hazards, restricted access, anything the client should know]</p><h2>Recommended additional work</h2><table><tbody><tr><th><p>Recommendation</p></th><th><p>Why</p></th><th><p>Best season</p></th><th><p>Est. cost</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Crew lead</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Client or site contact</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['client_name', 'company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name', 'weather']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-landscaping-installation-handover',
  NULL,
  NULL,
  'Landscape Installation & Handover',
  jsonb_build_object(
    'style', 'report',
    'category', 'Landscaping',
    'description', 'Hands over a finished install: what was planted and built, the irrigation as-built, the establishment schedule, and the warranty the client is signing for.',
    'html', $html$<h1>Landscape Installation and Handover</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><strong>Client:</strong> {{client_name}} &nbsp;·&nbsp; <strong>Project #:</strong> {{project_number}}</p><p><em><span style="color: rgb(140,148,162)">The client keeps this. Write it for someone who was not on site.</span></em></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'300'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'299'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ECompleted%20scheme%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'164'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="300" alt="Completed scheme"></p><h2>1. Scope installed</h2><table><tbody><tr><th><p>Element</p></th><th><p>Installed</p></th><th><p>Area or quantity</p></th><th><p>Notes</p></th></tr><tr><td><p>Soil preparation and grading</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Turf or seeding</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Planting beds</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Trees and specimen planting</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Hard landscaping</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Edging and mulch</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>2. Planting schedule</h2><p><em><span style="color: rgb(140,148,162)">Species and size as planted, not as specified, where the two differ.</span></em></p><table><tbody><tr><th><p>Qty</p></th><th><p>Species</p></th><th><p>Size at planting</p></th><th><p>Location</p></th><th><p>Substituted</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EPlanting%201%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Planting 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EPlanting%202%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Planting 2"></p><h2>3. Irrigation as-built</h2><table><tbody><tr><th><p>Zone</p></th><th><p>What it waters</p></th><th><p>Heads or emitters</p></th><th><p>Run time</p></th><th><p>Days</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><strong>Controller location:</strong> [Where it is] &nbsp;·&nbsp; <strong>Isolation valve:</strong> [Where it is]</p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EController%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Controller"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EValve%20or%20manifold%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Valve or manifold"></p><h2>4. Establishment care</h2><p><em><span style="color: rgb(140,148,162)">The first eight weeks decide whether any of this lives.</span></em></p><table><tbody><tr><th><p>Week</p></th><th><p>Watering</p></th><th><p>Mowing</p></th><th><p>Feed</p></th><th><p>Other</p></th></tr><tr><td><p>1 to 2</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>3 to 4</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>5 to 8</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Ongoing</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>5. Handover checks</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Site cleared of surplus material and waste</p></li><li data-type="taskItem" data-checked="false"><p>Irrigation tested zone by zone</p></li><li data-type="taskItem" data-checked="false"><p>Controller programmed and client shown how</p></li><li data-type="taskItem" data-checked="false"><p>Plant list and care notes handed over</p></li><li data-type="taskItem" data-checked="false"><p>Levels and drainage confirmed correct</p></li><li data-type="taskItem" data-checked="false"><p>Client walked the scheme</p></li></ul><h2>6. Warranty</h2><table><tbody><tr><th><p>Covered</p></th><th><p>Period</p></th><th><p>Conditions</p></th><th><p>Excluded</p></th></tr><tr><td><p>Planting</p></td><td><p>[Period]</p></td><td><p>[What the client must do]</p></td><td><p>[What voids it]</p></td></tr><tr><td><p>Turf</p></td><td><p>[Period]</p></td><td><p>[What the client must do]</p></td><td><p>[What voids it]</p></td></tr><tr><td><p>Irrigation</p></td><td><p>[Period]</p></td><td><p>[What the client must do]</p></td><td><p>[What voids it]</p></td></tr><tr><td><p>Hard landscaping</p></td><td><p>[Period]</p></td><td><p>[What the client must do]</p></td><td><p>[What voids it]</p></td></tr></tbody></table><h2>7. Notes for the client</h2><p>[Anything agreed on the day, and who to call]</p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Prepared by</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Client</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['client_name', 'company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name', 'project_number']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-landscaping-site-survey-quote',
  NULL,
  NULL,
  'Grounds Survey & Quotation',
  jsonb_build_object(
    'style', 'report',
    'category', 'Landscaping',
    'description', 'Walks a site before quoting: measured areas, what is there now, access and constraints, and a priced scope the client can say yes to.',
    'html', $html$<h1>Grounds Survey and Quotation</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><strong>Prepared for:</strong> {{client_name}} &nbsp;·&nbsp; <strong>Contact:</strong> {{client_contact}}</p><p><em><span style="color: rgb(140,148,162)">Measure it once, on site. A quote built from memory is a quote you lose money on.</span></em></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'300'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'299'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ESite%20overview%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'164'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="300" alt="Site overview"></p><h2>1. Site measurements</h2><table><tbody><tr><th><p>Area</p></th><th><p>Size</p></th><th><p>Surface</p></th><th><p>Condition</p></th><th><p>Notes</p></th></tr><tr><td><p>Lawn</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Planted beds</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Hedging</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Paths and hard surfaces</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Trees</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>2. Existing conditions</h2><table><tbody><tr><th><p>Item</p></th><th><p>Observation</p></th></tr><tr><td><p>Soil type and drainage</p></td><td><p>[What you found]</p></td></tr><tr><td><p>Aspect and shade</p></td><td><p>[What you found]</p></td></tr><tr><td><p>Water source on site</p></td><td><p>[Where, and pressure]</p></td></tr><tr><td><p>Existing irrigation</p></td><td><p>[Present, working, none]</p></td></tr><tr><td><p>Weeds, pests or disease</p></td><td><p>[What you saw]</p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EExisting%20condition%201%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Existing condition 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EExisting%20condition%202%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Existing condition 2"></p><h2>3. Access and constraints</h2><table><tbody><tr><th><p>Access route</p></th><th><p>Narrowest point</p></th><th><p>Machinery that fits</p></th><th><p>Waste removal</p></th><th><p>Parking</p></th></tr><tr><td><p>[Which side]</p></td><td><p>[Width]</p></td><td><p>[What fits]</p></td><td><p>[How]</p></td><td><p>[Where]</p></td></tr></tbody></table><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Overhead lines and buried services checked</p></li><li data-type="taskItem" data-checked="false"><p>Working hours and noise limits confirmed</p></li><li data-type="taskItem" data-checked="false"><p>Pets, children or public access to plan around</p></li><li data-type="taskItem" data-checked="false"><p>Neighbouring boundaries agreed with the client</p></li></ul><h2>4. Proposed scope</h2><table><tbody><tr><th><p>Item</p></th><th><p>What is included</p></th><th><p>Quantity</p></th><th><p>Price</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>5. Optional extras</h2><table><tbody><tr><th><p>Item</p></th><th><p>Why we suggest it</p></th><th><p>Price</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>6. Quotation summary</h2><table><tbody><tr><th><p>Scope total</p></th><th><p>Extras selected</p></th><th><p>Subtotal</p></th><th><p>Tax</p></th><th><p>Total</p></th></tr><tr><td><p>[Amount]</p></td><td><p>[Amount]</p></td><td><p>[Amount]</p></td><td><p>[Amount]</p></td><td><p>[Amount]</p></td></tr></tbody></table><p><strong>Valid until:</strong> [Date] &nbsp;·&nbsp; <strong>Lead time:</strong> [How long] &nbsp;·&nbsp; <strong>Best season to start:</strong> [Season]</p><h2>7. What happens next</h2><p>[How the client accepts, and what we need from them]</p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Prepared by</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Client acceptance</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['client_name', 'client_contact', 'company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
